def minPath(grid, k):
    n = len(grid)
    if k == 1:
        min_val = min(min(row) for row in grid)
        return [min_val]

    # Precompute positions of each value
    pos = [None] * (n * n + 1)
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # For each cell, find the smallest neighbor value
    best_next = [[None] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            neighbors = []
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    neighbors.append(grid[ni][nj])
            best_next[i][j] = min(neighbors)

    # Greedy: start from the smallest value cell, then repeatedly move to the neighbor with smallest value
    # But this greedy may not be optimal for k>2, so we need a more careful approach.
    # Since values are unique and we need lexicographically smallest sequence, we can do BFS with pruning.

    # We'll do a BFS that keeps for each length the best path ending at each cell.
    # dp[length][cell] = best path (list) of that length ending at that cell
    # We only keep the lexicographically smallest path for each (length, cell)

    # Initialize for length 1
    dp = {1: {}}  # length -> dict cell -> path list
    for i in range(n):
        for j in range(n):
            dp[1][(i,j)] = [grid[i][j]]

    for length in range(2, k+1):
        dp[length] = {}
        for (i,j), path in dp[length-1].items():
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    new_path = path + [grid[ni][nj]]
                    key = (ni,nj)
                    if key not in dp[length] or new_path < dp[length][key]:
                        dp[length][key] = new_path

    # Find the overall minimum path of length k
    best = None
    for path in dp[k].values():
        if best is None or path < best:
            best = path
    return best
